"use client";

import { useState } from "react";
import { Play, Trash2, ExternalLink, Check } from "lucide-react";
import { Button } from "@/components/ui/button";
import { cn } from "@/lib/utils";
import type { Task, TaskStatus, TaskPriority } from "@/lib/types";

const PRIORITY_COLORS: Record<TaskPriority, string> = {
  urgent: "bg-red-500/20 text-red-400 border-red-500/30",
  high: "bg-orange-500/20 text-orange-400 border-orange-500/30",
  medium: "bg-yellow-500/20 text-yellow-400 border-yellow-500/30",
  low: "bg-muted text-muted-foreground border-border",
};

const STATUS_COLORS: Record<TaskStatus, string> = {
  todo: "border-border text-muted-foreground",
  "in-progress": "bg-blue-500/20 text-blue-400 border-blue-500/30",
  done: "bg-green-500/20 text-green-400 border-green-500/30",
};

const STATUS_LABELS: Record<TaskStatus, string> = {
  todo: "todo",
  "in-progress": "in progress",
  done: "done",
};

const NEXT_STATUS: Record<TaskStatus, TaskStatus> = {
  todo: "in-progress",
  "in-progress": "done",
  done: "todo",
};

interface TaskCardProps {
  task: Task;
  onUpdate: (taskId: string, updates: Partial<Pick<Task, "title" | "description" | "status" | "priority">>) => void;
  onDelete: (taskId: string) => void;
  onDelegate: (taskId: string) => void;
  onSelectAgent: (agentId: string) => void;
}

export function TaskCard({ task, onUpdate, onDelete, onDelegate, onSelectAgent }: TaskCardProps) {
  const [editing, setEditing] = useState(false);
  const [editTitle, setEditTitle] = useState(task.title);
  const [editDesc, setEditDesc] = useState(task.description);

  const handleSaveEdit = () => {
    if (!editTitle.trim()) return;
    onUpdate(task.id, { title: editTitle.trim(), description: editDesc.trim() });
    setEditing(false);
  };

  const handleCancelEdit = () => {
    setEditTitle(task.title);
    setEditDesc(task.description);
    setEditing(false);
  };

  return (
    <div className="group rounded-md border bg-card p-3 text-xs">
      <div className="flex items-start justify-between gap-2">
        <div className="flex items-center gap-1.5 min-w-0">
          <span
            className={cn("shrink-0 rounded px-1.5 py-0.5 text-[10px] font-medium border", PRIORITY_COLORS[task.priority])}
          >
            {task.priority}
          </span>
          {editing ? (
            <input
              className="min-w-0 flex-1 bg-transparent font-medium outline-none border-b border-primary"
              value={editTitle}
              onChange={(e) => setEditTitle(e.target.value)}
              onKeyDown={(e) => {
                if (e.key === "Enter") handleSaveEdit();
                if (e.key === "Escape") handleCancelEdit();
              }}
              autoFocus
            />
          ) : (
            <span
              className={cn(
                "truncate font-medium cursor-pointer",
                task.status === "done" && "line-through text-muted-foreground"
              )}
              onDoubleClick={() => setEditing(true)}
            >
              {task.title}
            </span>
          )}
        </div>
        <div className="flex shrink-0 items-center gap-0.5 opacity-0 group-hover:opacity-100 transition-opacity">
          {!task.agentId && task.status !== "done" && (
            <Button
              variant="ghost"
              size="icon-xs"
              onClick={() => onDelegate(task.id)}
              title="Delegate to agent"
            >
              <Play className="size-3" />
            </Button>
          )}
          <Button
            variant="ghost"
            size="icon-xs"
            onClick={() => onDelete(task.id)}
            title="Delete task"
          >
            <Trash2 className="size-3" />
          </Button>
        </div>
      </div>

      {editing ? (
        <div className="mt-2 space-y-2">
          <textarea
            className="w-full rounded border bg-transparent p-1.5 text-xs outline-none resize-none"
            value={editDesc}
            onChange={(e) => setEditDesc(e.target.value)}
            rows={2}
            placeholder="Description..."
          />
          <div className="flex gap-1">
            <Button size="xs" onClick={handleSaveEdit}>
              <Check className="size-3 mr-1" />
              Save
            </Button>
            <Button size="xs" variant="ghost" onClick={handleCancelEdit}>
              Cancel
            </Button>
          </div>
        </div>
      ) : (
        task.description && (
          <p className="mt-1 text-muted-foreground line-clamp-2">{task.description}</p>
        )
      )}

      <div className="mt-2 flex items-center justify-between">
        <button
          className={cn(
            "rounded-full border px-2 py-0.5 text-[10px] font-medium transition-colors hover:brightness-125",
            STATUS_COLORS[task.status]
          )}
          onClick={() => onUpdate(task.id, { status: NEXT_STATUS[task.status] })}
          title={`Click to change to "${STATUS_LABELS[NEXT_STATUS[task.status]]}"`}
        >
          {STATUS_LABELS[task.status]}
        </button>

        {task.agentId && (
          <button
            className="flex items-center gap-1 text-[10px] text-primary hover:underline"
            onClick={() => onSelectAgent(task.agentId!)}
          >
            <ExternalLink className="size-2.5" />
            view agent
          </button>
        )}
      </div>
    </div>
  );
}

"use client";

import { useState } from "react";
import { Plus } from "lucide-react";
import { Button } from "@/components/ui/button";
import type { TaskPriority } from "@/lib/types";

interface TaskCreateFormProps {
  onCreate: (title: string, description: string, priority: TaskPriority) => void;
}

const PRIORITIES: TaskPriority[] = ["low", "medium", "high", "urgent"];

export function TaskCreateForm({ onCreate }: TaskCreateFormProps) {
  const [title, setTitle] = useState("");
  const [description, setDescription] = useState("");
  const [priority, setPriority] = useState<TaskPriority>("medium");

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    if (!title.trim()) return;
    onCreate(title.trim(), description.trim(), priority);
    setTitle("");
    setDescription("");
    setPriority("medium");
  };

  return (
    <form onSubmit={handleSubmit} className="space-y-2 border-b p-3">
      <input
        className="w-full rounded border bg-transparent px-2 py-1.5 text-xs outline-none focus:border-primary"
        placeholder="Task title..."
        value={title}
        onChange={(e) => setTitle(e.target.value)}
      />
      <textarea
        className="w-full rounded border bg-transparent px-2 py-1.5 text-xs outline-none resize-none focus:border-primary"
        placeholder="Description (optional)..."
        value={description}
        onChange={(e) => setDescription(e.target.value)}
        rows={2}
      />
      <div className="flex items-center justify-between">
        <select
          className="rounded border bg-transparent px-2 py-1 text-xs outline-none"
          value={priority}
          onChange={(e) => setPriority(e.target.value as TaskPriority)}
        >
          {PRIORITIES.map((p) => (
            <option key={p} value={p}>
              {p}
            </option>
          ))}
        </select>
        <Button type="submit" size="xs" disabled={!title.trim()}>
          <Plus className="size-3 mr-1" />
          Create
        </Button>
      </div>
    </form>
  );
}

"use client";

import { useMemo, useState } from "react";
import { ChevronDown, Plus, X } from "lucide-react";
import { Button } from "@/components/ui/button";
import { cn } from "@/lib/utils";
import { TaskCard } from "./task-card";
import { TaskCreateForm } from "./task-create-form";
import type { Task, TaskPriority } from "@/lib/types";

interface TaskPanelProps {
  tasks: Task[];
  onCreateTask: (title: string, description: string, priority: TaskPriority) => void;
  onUpdateTask: (taskId: string, updates: Partial<Pick<Task, "title" | "description" | "status" | "priority">>) => void;
  onDeleteTask: (taskId: string) => void;
  onDelegateTask: (taskId: string) => void;
  onSelectAgent: (agentId: string) => void;
  onClose: () => void;
}

export function TaskPanel({
  tasks,
  onCreateTask,
  onUpdateTask,
  onDeleteTask,
  onDelegateTask,
  onSelectAgent,
  onClose,
}: TaskPanelProps) {
  const [showCreate, setShowCreate] = useState(false);
  const [showDone, setShowDone] = useState(false);

  const grouped = useMemo(() => {
    const inProgress = tasks.filter((t) => t.status === "in-progress");
    const todo = tasks.filter((t) => t.status === "todo");
    const done = tasks.filter((t) => t.status === "done");
    return { inProgress, todo, done };
  }, [tasks]);

  return (
    <div className="flex h-full flex-col">
      {/* Header */}
      <div className="flex items-center justify-between border-b px-3 py-2">
        <span className="text-xs font-semibold">Tasks</span>
        <div className="flex items-center gap-1">
          <Button
            variant="ghost"
            size="icon-xs"
            onClick={() => setShowCreate((v) => !v)}
            title="New task"
          >
            <Plus className="size-3.5" />
          </Button>
          <Button variant="ghost" size="icon-xs" onClick={onClose} title="Close panel">
            <X className="size-3.5" />
          </Button>
        </div>
      </div>

      {/* Create form */}
      {showCreate && (
        <TaskCreateForm
          onCreate={(title, description, priority) => {
            onCreateTask(title, description, priority);
            setShowCreate(false);
          }}
        />
      )}

      {/* Task list */}
      <div className="flex-1 overflow-y-auto">
        {tasks.length === 0 && !showCreate && (
          <div className="flex h-32 items-center justify-center text-xs text-muted-foreground">
            No tasks yet
          </div>
        )}

        {/* In Progress */}
        {grouped.inProgress.length > 0 && (
          <TaskGroup label="In Progress" count={grouped.inProgress.length}>
            {grouped.inProgress.map((task) => (
              <TaskCard
                key={task.id}
                task={task}
                onUpdate={onUpdateTask}
                onDelete={onDeleteTask}
                onDelegate={onDelegateTask}
                onSelectAgent={onSelectAgent}
              />
            ))}
          </TaskGroup>
        )}

        {/* Todo */}
        {grouped.todo.length > 0 && (
          <TaskGroup label="Todo" count={grouped.todo.length}>
            {grouped.todo.map((task) => (
              <TaskCard
                key={task.id}
                task={task}
                onUpdate={onUpdateTask}
                onDelete={onDeleteTask}
                onDelegate={onDelegateTask}
                onSelectAgent={onSelectAgent}
              />
            ))}
          </TaskGroup>
        )}

        {/* Done (collapsible) */}
        {grouped.done.length > 0 && (
          <div className="border-t">
            <button
              className="flex w-full items-center justify-between px-3 py-2 text-xs text-muted-foreground hover:text-foreground transition-colors"
              onClick={() => setShowDone((v) => !v)}
            >
              <span className="font-semibold">Done ({grouped.done.length})</span>
              <ChevronDown
                className={cn("size-3 transition-transform", showDone && "rotate-180")}
              />
            </button>
            {showDone && (
              <div className="space-y-2 px-3 pb-3">
                {grouped.done.map((task) => (
                  <TaskCard
                    key={task.id}
                    task={task}
                    onUpdate={onUpdateTask}
                    onDelete={onDeleteTask}
                    onDelegate={onDelegateTask}
                    onSelectAgent={onSelectAgent}
                  />
                ))}
              </div>
            )}
          </div>
        )}
      </div>
    </div>
  );
}

function TaskGroup({
  label,
  count,
  children,
}: {
  label: string;
  count: number;
  children: React.ReactNode;
}) {
  return (
    <div className="border-t">
      <div className="px-3 py-2 text-xs font-semibold text-muted-foreground">
        {label} ({count})
      </div>
      <div className="space-y-2 px-3 pb-3">{children}</div>
    </div>
  );
}

