"use client";

/**
 * React hook that manages the WebSocket connection to the thos relay server.
 *
 * Supports multiple concurrent agents. Each agent has its own status,
 * message history, label, and tmux session name tracked in a Map keyed
 * by agent ID. The `activeAgentId` determines which agent's chat is shown.
 *
 * Resilience features:
 * - Handles `message_history` replay from server on connect/reconnect.
 * - Handles `cli_disconnected` / `cli_connected` events.
 * - Deduplicates messages using a per-agent Set of seen message IDs.
 * - Robust reconnection guard (clears previous timer before scheduling).
 */

import { useCallback, useEffect, useMemo, useRef, useState } from "react";
import type {
  AgentInfo,
  AgentStatus,
  ChatMessage,
  ClaudeAssistant,
  ClaudeControlRequest,
  ClaudeMessage,
  ClaudeResult,
  ClaudeSystemInit,
  ServerMessage,
  ServerMessageHistory,
  ServerTaskList,
  ServerTaskUpdated,
  ServerTaskDeleted,
  Task,
  TaskPriority,
  ToolCallInfo,
  UserQuestion,
} from "@/lib/types";

const WS_URL = "ws://localhost:9900/browser";

/** Per-agent client state. */
export interface AgentClientState {
  status: AgentStatus;
  messages: ChatMessage[];
  /** Raw Claude NDJSON messages for debug view. */
  rawMessages: ClaudeMessage[];
  label: string;
  tmuxSession: string | null;
  createdAt: number;
}

/**
 * Extract displayable text from a Claude assistant message.
 * Content blocks may be text, tool_use, or tool_result — each is
 * handled defensively since the array structure can vary.
 */
function extractText(msg: ClaudeAssistant): string {
  const blocks = msg.message?.content;
  if (!blocks || !Array.isArray(blocks)) return "";
  return blocks
    .map((b) => {
      if (b.type === "text") return b.text;
      if (b.type === "tool_use") return `[tool_use: ${b.name}]`;
      if (b.type === "tool_result") return `[tool_result: ${b.content}]`;
      return "";
    })
    .filter(Boolean)
    .join("\n");
}

/** Module-level counter for generating unique message IDs. */
let msgCounter = 0;
function nextId() {
  return `msg-${Date.now()}-${++msgCounter}`;
}

/**
 * Convert a server relay message into a ChatMessage, or null if it shouldn't be displayed.
 * Used both for live messages and for replaying message_history.
 */
function relayChatMessage(agentId: string, relayMsg: ServerMessage): ChatMessage | null {
  if (relayMsg.type === "relay") {
    const msg = relayMsg.message;

    if (msg.type === "system" && (msg as { subtype?: string }).subtype === "init") {
      const init = msg as ClaudeSystemInit;
      return {
        id: nextId(),
        role: "system",
        content: `Session started — model: ${init.model}, cwd: ${init.cwd}`,
        timestamp: Date.now(),
      };
    }

    if (msg.type === "assistant") {
      const assistant = msg as ClaudeAssistant;
      const text = extractText(assistant);
      if (!text) return null;

      const blocks = assistant.message?.content ?? [];
      const hasText = blocks.some((b) => b.type === "text" && b.text.trim());
      const toolCalls: ToolCallInfo[] = blocks
        .filter((b) => b.type === "tool_use")
        .map((b) => ({
          name: (b as { name: string }).name,
          toolUseId: (b as { id: string }).id,
        }));
      const isToolOnly = !hasText && toolCalls.length > 0;

      return {
        id: nextId(),
        role: "assistant",
        content: text,
        timestamp: Date.now(),
        toolCalls,
        isToolOnly,
      };
    }

    if (msg.type === "result") {
      const result = msg as ClaudeResult;
      const summary = result.is_error
        ? `Error: ${result.error}`
        : `Done — ${result.num_turns ?? "?"} turns, $${(result.cost_usd ?? 0).toFixed(4)}, ${((result.duration_ms ?? 0) / 1000).toFixed(1)}s`;
      return {
        id: nextId(),
        role: "system",
        content: summary,
        timestamp: Date.now(),
      };
    }

    if (msg.type === "control_request") {
      const cr = msg as ClaudeControlRequest;

      // AskUserQuestion gets its own UI instead of generic Allow/Deny
      if (cr.request.tool_name === "AskUserQuestion") {
        const input = cr.request.input as { questions?: UserQuestion[] };
        const questions = Array.isArray(input.questions) ? input.questions : [];
        return {
          id: nextId(),
          role: "system",
          content: "Question from Claude",
          timestamp: Date.now(),
          userQuestion: {
            requestId: cr.request_id,
            questions,
          },
        };
      }

      return {
        id: nextId(),
        role: "system",
        content: `Tool approval requested: ${cr.request.tool_name}`,
        timestamp: Date.now(),
        controlRequest: {
          id: cr.request_id,
          tool_name: cr.request.tool_name,
          input: cr.request.input,
        },
      };
    }
  }

  if (relayMsg.type === "error" && relayMsg.agentId === agentId) {
    return {
      id: nextId(),
      role: "system",
      content: `Error: ${relayMsg.error}`,
      timestamp: Date.now(),
    };
  }

  return null;
}

export function useWebSocket() {
  const wsRef = useRef<WebSocket | null>(null);
  const reconnectTimer = useRef<ReturnType<typeof setTimeout> | null>(null);
  const [connected, setConnected] = useState(false);

  // Multi-agent state
  const [agents, setAgents] = useState<Map<string, AgentClientState>>(new Map());
  const [agentOrder, setAgentOrder] = useState<string[]>([]);
  const [activeAgentId, setActiveAgentId] = useState<string | null>(null);

  // Task state
  const [tasks, setTasks] = useState<Task[]>([]);

  // Per-agent deduplication: track count of processed messages per agent
  // to avoid duplicating messages already in local state during history replay.
  const processedCountRef = useRef<Map<string, number>>(new Map());

  /** Immutably update a single agent's state in the Map. */
  const updateAgent = useCallback(
    (agentId: string, updater: (prev: AgentClientState) => AgentClientState) => {
      setAgents((prev) => {
        const existing = prev.get(agentId);
        if (!existing) return prev;
        const next = new Map(prev);
        next.set(agentId, updater(existing));
        return next;
      });
    },
    []
  );

  const connect = useCallback(() => {
    if (wsRef.current?.readyState === WebSocket.OPEN) return;
    if (wsRef.current) {
      wsRef.current.close();
      wsRef.current = null;
    }

    const ws = new WebSocket(WS_URL);
    wsRef.current = ws;

    ws.onopen = () => setConnected(true);

    ws.onclose = () => {
      setConnected(false);
      wsRef.current = null;
      // Reconnection guard: clear any existing timer before scheduling
      if (reconnectTimer.current) clearTimeout(reconnectTimer.current);
      reconnectTimer.current = setTimeout(() => connect(), 2000);
    };

    ws.onerror = () => {
      // onclose will fire after onerror, which triggers reconnect
    };

    ws.onmessage = (event) => {
      let data: ServerMessage;
      try {
        data = JSON.parse(event.data as string);
      } catch {
        return;
      }

      // ── task_list: full task list from server ──
      if (data.type === "task_list") {
        setTasks((data as ServerTaskList).tasks);
        return;
      }

      // ── task_updated: single task changed ──
      if (data.type === "task_updated") {
        const updated = (data as ServerTaskUpdated).task;
        setTasks((prev) => prev.map((t) => (t.id === updated.id ? updated : t)));
        return;
      }

      // ── task_deleted: remove task ──
      if (data.type === "task_deleted") {
        const deletedId = (data as ServerTaskDeleted).taskId;
        setTasks((prev) => prev.filter((t) => t.id !== deletedId));
        return;
      }

      // ── message_history: replay full history from server ──
      if (data.type === "message_history") {
        const historyMsg = data as ServerMessageHistory;
        const agentId = historyMsg.agentId;
        const serverMessages = historyMsg.messages;

        // Convert all server messages to ChatMessages + extract raw Claude messages
        const chatMessages: ChatMessage[] = [];
        const rawMessages: ClaudeMessage[] = [];
        for (const sm of serverMessages) {
          if (sm.type === "relay") {
            rawMessages.push(sm.message);
          }
          const cm = relayChatMessage(agentId, sm);
          if (cm) chatMessages.push(cm);
        }

        // Skip messages already processed locally (dedup)
        const alreadyProcessed = processedCountRef.current.get(agentId) ?? 0;
        const newMessages = chatMessages.slice(alreadyProcessed);

        if (newMessages.length > 0) {
          setAgents((prev) => {
            const existing = prev.get(agentId);
            if (!existing) {
              // Agent not yet in local state — create it
              const next = new Map(prev);
              next.set(agentId, {
                status: "idle",
                messages: chatMessages, // use full history for new agent
                rawMessages,
                label: "",
                tmuxSession: null,
                createdAt: 0,
              });
              return next;
            }
            // Replace messages with full server history (source of truth)
            const next = new Map(prev);
            next.set(agentId, { ...existing, messages: chatMessages, rawMessages });
            return next;
          });
        }

        processedCountRef.current.set(agentId, chatMessages.length);
        return;
      }

      // ── history_cleared: wipe local messages for this agent ──
      if (data.type === "history_cleared") {
        updateAgent(data.agentId, (prev) => ({
          ...prev,
          messages: [],
          rawMessages: [],
        }));
        processedCountRef.current.set(data.agentId, 0);
        return;
      }

      // ── cli_disconnected: show system message ──
      if (data.type === "cli_disconnected") {
        updateAgent(data.agentId, (prev) => ({
          ...prev,
          messages: [
            ...prev.messages,
            {
              id: nextId(),
              role: "system",
              content: "CLI session ended",
              timestamp: Date.now(),
            },
          ],
        }));
        return;
      }

      // ── cli_connected: show system message ──
      if (data.type === "cli_connected") {
        updateAgent(data.agentId, (prev) => ({
          ...prev,
          messages: [
            ...prev.messages,
            {
              id: nextId(),
              role: "system",
              content: "CLI reconnected",
              timestamp: Date.now(),
            },
          ],
        }));
        return;
      }

      // ── agent_list: reconcile sidebar state from server ──
      if (data.type === "agent_list") {
        const serverAgents = data.agents as AgentInfo[];
        setAgents((prev) => {
          const next = new Map(prev);
          const serverIds = new Set(serverAgents.map((a) => a.agentId));

          // Update or add agents from server
          for (const info of serverAgents) {
            const existing = next.get(info.agentId);
            if (existing) {
              next.set(info.agentId, {
                ...existing,
                status: info.status,
                tmuxSession: info.tmuxSession,
                label: info.label,
              });
            } else {
              next.set(info.agentId, {
                status: info.status,
                messages: [],
                rawMessages: [],
                label: info.label,
                tmuxSession: info.tmuxSession,
                createdAt: info.createdAt,
              });
            }
          }

          // Remove agents no longer on the server
          for (const id of next.keys()) {
            if (!serverIds.has(id)) {
              next.delete(id);
            }
          }

          return next;
        });
        setAgentOrder(serverAgents.map((a) => a.agentId));
        return;
      }

      // ── spawned: auto-select the newly created agent ──
      if (data.type === "spawned") {
        setActiveAgentId(data.agentId);
        return;
      }

      // ── status: update a specific agent's status ──
      if (data.type === "status") {
        updateAgent(data.agentId, (prev) => ({ ...prev, status: data.status }));
        return;
      }

      // ── error: append to agent's message list ──
      if (data.type === "error") {
        updateAgent(data.agentId, (prev) => ({
          ...prev,
          messages: [
            ...prev.messages,
            {
              id: nextId(),
              role: "system",
              content: `Error: ${data.error}`,
              timestamp: Date.now(),
            },
          ],
        }));
        // Track processed count for dedup
        processedCountRef.current.set(
          data.agentId,
          (processedCountRef.current.get(data.agentId) ?? 0) + 1
        );
        return;
      }

      // ── relay: append claude message to agent's history ──
      if (data.type === "relay") {
        const agentId = data.agentId;
        const rawMsg = data.message;
        const chatMsg = relayChatMessage(agentId, data);

        updateAgent(agentId, (prev) => ({
          ...prev,
          rawMessages: [...prev.rawMessages, rawMsg],
          messages: chatMsg ? [...prev.messages, chatMsg] : prev.messages,
        }));
        if (chatMsg) {
          // Track processed count for dedup
          processedCountRef.current.set(
            agentId,
            (processedCountRef.current.get(agentId) ?? 0) + 1
          );
        }
        return;
      }
    };
  }, [updateAgent]);

  useEffect(() => {
    connect();
    return () => {
      if (reconnectTimer.current) clearTimeout(reconnectTimer.current);
      wsRef.current?.close();
    };
  }, [connect]);

  const send = useCallback((data: object) => {
    if (wsRef.current?.readyState === WebSocket.OPEN) {
      wsRef.current.send(JSON.stringify(data));
    }
  }, []);

  const spawnAgent = useCallback(
    (prompt: string) => {
      send({ type: "spawn", prompt });
    },
    [send]
  );

  const sendMessage = useCallback(
    (content: string) => {
      if (!activeAgentId) return;
      // Optimistically add user message to local state
      updateAgent(activeAgentId, (prev) => ({
        ...prev,
        messages: [
          ...prev.messages,
          {
            id: nextId(),
            role: "user",
            content,
            timestamp: Date.now(),
          },
        ],
      }));
      send({ type: "send_message", agentId: activeAgentId, content });
    },
    [send, activeAgentId, updateAgent]
  );

  const respondToControl = useCallback(
    (requestId: string, allow: boolean) => {
      if (!activeAgentId) return;
      send({ type: "control_response", agentId: activeAgentId, request_id: requestId, allow });
      updateAgent(activeAgentId, (prev) => ({
        ...prev,
        messages: prev.messages.map((m) =>
          m.controlRequest?.id === requestId
            ? { ...m, controlRequest: { ...m.controlRequest, resolved: true } }
            : m
        ),
      }));
    },
    [send, activeAgentId, updateAgent]
  );

  /** Respond to an AskUserQuestion control request with the user's selections. */
  const respondToUserQuestion = useCallback(
    (requestId: string, answers: Record<string, string>) => {
      if (!activeAgentId) return;
      send({
        type: "control_response",
        agentId: activeAgentId,
        request_id: requestId,
        allow: true,
        answers,
      });
      updateAgent(activeAgentId, (prev) => ({
        ...prev,
        messages: prev.messages.map((m) =>
          m.userQuestion?.requestId === requestId
            ? { ...m, userQuestion: { ...m.userQuestion, resolved: true } }
            : m
        ),
      }));
    },
    [send, activeAgentId, updateAgent]
  );

  // ── Agent management actions ──────────────────────────────────────────────

  const killAgent = useCallback(
    (agentId: string) => {
      send({ type: "kill_agent", agentId });
    },
    [send]
  );

  const deleteAgent = useCallback(
    (agentId: string) => {
      send({ type: "delete_agent", agentId });
      // Deselect if we just deleted the active agent
      setActiveAgentId((prev) => (prev === agentId ? null : prev));
    },
    [send]
  );

  const renameAgent = useCallback(
    (agentId: string, label: string) => {
      send({ type: "rename_agent", agentId, label });
    },
    [send]
  );

  const clearHistory = useCallback(
    (agentId: string) => {
      send({ type: "clear_history", agentId });
    },
    [send]
  );

  // Derived values for the active agent
  const activeAgent = activeAgentId ? agents.get(activeAgentId) : undefined;
  const activeStatus = useMemo<AgentStatus>(
    () => activeAgent?.status ?? "idle",
    [activeAgent?.status]
  );
  const activeMessages = useMemo<ChatMessage[]>(
    () => activeAgent?.messages ?? [],
    [activeAgent?.messages]
  );
  const activeRawMessages = useMemo<ClaudeMessage[]>(
    () => activeAgent?.rawMessages ?? [],
    [activeAgent?.rawMessages]
  );

  return {
    connected,
    agents,
    agentOrder,
    activeAgentId,
    setActiveAgentId,
    activeStatus,
    activeMessages,
    activeRawMessages,
    spawnAgent,
    sendMessage,
    respondToControl,
    respondToUserQuestion,
    killAgent,
    deleteAgent,
    renameAgent,
    clearHistory,
  };
}

"use client";

/**
 * React hook that manages the WebSocket connection to the thos relay server.
 *
 * Supports multiple concurrent agents. Each agent has its own status,
 * message history, label, and tmux session name tracked in a Map keyed
 * by agent ID. The `activeAgentId` determines which agent's chat is shown.
 *
 * Resilience features:
 * - Handles `message_history` replay from server on connect/reconnect.
 * - Handles `cli_disconnected` / `cli_connected` events.
 * - Deduplicates messages using a per-agent Set of seen message IDs.
 * - Robust reconnection guard (clears previous timer before scheduling).
 */

import { useCallback, useEffect, useMemo, useRef, useState } from "react";
import type {
  AgentInfo,
  AgentStatus,
  ChatMessage,
  ClaudeAssistant,
  ClaudeControlRequest,
  ClaudeMessage,
  ClaudeResult,
  ClaudeSystemInit,
  ServerMessage,
  ServerMessageHistory,
  ServerTaskList,
  ServerTaskUpdated,
  ServerTaskDeleted,
  Task,
  TaskPriority,
  ToolCallInfo,
  UserQuestion,
} from "@/lib/types";

const WS_URL = "ws://localhost:9900/browser";

/** Per-agent client state. */
export interface AgentClientState {
  status: AgentStatus;
  messages: ChatMessage[];
  /** Raw Claude NDJSON messages for debug view. */
  rawMessages: ClaudeMessage[];
  label: string;
  tmuxSession: string | null;
  createdAt: number;
}

/**
 * Extract displayable text from a Claude assistant message.
 * Content blocks may be text, tool_use, or tool_result — each is
 * handled defensively since the array structure can vary.
 */
function extractText(msg: ClaudeAssistant): string {
  const blocks = msg.message?.content;
  if (!blocks || !Array.isArray(blocks)) return "";
  return blocks
    .map((b) => {
      if (b.type === "text") return b.text;
      if (b.type === "tool_use") return `[tool_use: ${b.name}]`;
      if (b.type === "tool_result") return `[tool_result: ${b.content}]`;
      return "";
    })
    .filter(Boolean)
    .join("\n");
}

/** Module-level counter for generating unique message IDs. */
let msgCounter = 0;
function nextId() {
  return `msg-${Date.now()}-${++msgCounter}`;
}

/**
 * Convert a server relay message into a ChatMessage, or null if it shouldn't be displayed.
 * Used both for live messages and for replaying message_history.
 */
function relayChatMessage(agentId: string, relayMsg: ServerMessage): ChatMessage | null {
  if (relayMsg.type === "relay") {
    const msg = relayMsg.message;

    if (msg.type === "system" && (msg as { subtype?: string }).subtype === "init") {
      const init = msg as ClaudeSystemInit;
      return {
        id: nextId(),
        role: "system",
        content: `Session started — model: ${init.model}, cwd: ${init.cwd}`,
        timestamp: Date.now(),
      };
    }

    if (msg.type === "assistant") {
      const assistant = msg as ClaudeAssistant;
      const text = extractText(assistant);
      if (!text) return null;

      const blocks = assistant.message?.content ?? [];
      const hasText = blocks.some((b) => b.type === "text" && b.text.trim());
      const toolCalls: ToolCallInfo[] = blocks
        .filter((b) => b.type === "tool_use")
        .map((b) => ({
          name: (b as { name: string }).name,
          toolUseId: (b as { id: string }).id,
        }));
      const isToolOnly = !hasText && toolCalls.length > 0;

      return {
        id: nextId(),
        role: "assistant",
        content: text,
        timestamp: Date.now(),
        toolCalls,
        isToolOnly,
      };
    }

    if (msg.type === "result") {
      const result = msg as ClaudeResult;
      const summary = result.is_error
        ? `Error: ${result.error}`
        : `Done — ${result.num_turns ?? "?"} turns, $${(result.cost_usd ?? 0).toFixed(4)}, ${((result.duration_ms ?? 0) / 1000).toFixed(1)}s`;
      return {
        id: nextId(),
        role: "system",
        content: summary,
        timestamp: Date.now(),
      };
    }

    if (msg.type === "control_request") {
      const cr = msg as ClaudeControlRequest;

      // AskUserQuestion gets its own UI instead of generic Allow/Deny
      if (cr.request.tool_name === "AskUserQuestion") {
        const input = cr.request.input as { questions?: UserQuestion[] };
        const questions = Array.isArray(input.questions) ? input.questions : [];
        return {
          id: nextId(),
          role: "system",
          content: "Question from Claude",
          timestamp: Date.now(),
          userQuestion: {
            requestId: cr.request_id,
            questions,
          },
        };
      }

      return {
        id: nextId(),
        role: "system",
        content: `Tool approval requested: ${cr.request.tool_name}`,
        timestamp: Date.now(),
        controlRequest: {
          id: cr.request_id,
          tool_name: cr.request.tool_name,
          input: cr.request.input,
        },
      };
    }
  }

  if (relayMsg.type === "error" && relayMsg.agentId === agentId) {
    return {
      id: nextId(),
      role: "system",
      content: `Error: ${relayMsg.error}`,
      timestamp: Date.now(),
    };
  }

  return null;
}

export function useWebSocket() {
  const wsRef = useRef<WebSocket | null>(null);
  const reconnectTimer = useRef<ReturnType<typeof setTimeout> | null>(null);
  const [connected, setConnected] = useState(false);

  // Multi-agent state
  const [agents, setAgents] = useState<Map<string, AgentClientState>>(new Map());
  const [agentOrder, setAgentOrder] = useState<string[]>([]);
  const [activeAgentId, setActiveAgentId] = useState<string | null>(null);

  // Task state
  const [tasks, setTasks] = useState<Task[]>([]);

  // Per-agent deduplication: track count of processed messages per agent
  // to avoid duplicating messages already in local state during history replay.
  const processedCountRef = useRef<Map<string, number>>(new Map());

  /** Immutably update a single agent's state in the Map. */
  const updateAgent = useCallback(
    (agentId: string, updater: (prev: AgentClientState) => AgentClientState) => {
      setAgents((prev) => {
        const existing = prev.get(agentId);
        if (!existing) return prev;
        const next = new Map(prev);
        next.set(agentId, updater(existing));
        return next;
      });
    },
    []
  );

  const connect = useCallback(() => {
    if (wsRef.current?.readyState === WebSocket.OPEN) return;
    if (wsRef.current) {
      wsRef.current.close();
      wsRef.current = null;
    }

    const ws = new WebSocket(WS_URL);
    wsRef.current = ws;

    ws.onopen = () => setConnected(true);

    ws.onclose = () => {
      setConnected(false);
      wsRef.current = null;
      // Reconnection guard: clear any existing timer before scheduling
      if (reconnectTimer.current) clearTimeout(reconnectTimer.current);
      reconnectTimer.current = setTimeout(() => connect(), 2000);
    };

    ws.onerror = () => {
      // onclose will fire after onerror, which triggers reconnect
    };

    ws.onmessage = (event) => {
      let data: ServerMessage;
      try {
        data = JSON.parse(event.data as string);
      } catch {
        return;
      }

      // ── task_list: full task list from server ──
      if (data.type === "task_list") {
        setTasks((data as ServerTaskList).tasks);
        return;
      }

      // ── task_updated: single task changed ──
      if (data.type === "task_updated") {
        const updated = (data as ServerTaskUpdated).task;
        setTasks((prev) => prev.map((t) => (t.id === updated.id ? updated : t)));
        return;
      }

      // ── task_deleted: remove task ──
      if (data.type === "task_deleted") {
        const deletedId = (data as ServerTaskDeleted).taskId;
        setTasks((prev) => prev.filter((t) => t.id !== deletedId));
        return;
      }

      // ── message_history: replay full history from server ──
      if (data.type === "message_history") {
        const historyMsg = data as ServerMessageHistory;
        const agentId = historyMsg.agentId;
        const serverMessages = historyMsg.messages;

        // Convert all server messages to ChatMessages + extract raw Claude messages
        const chatMessages: ChatMessage[] = [];
        const rawMessages: ClaudeMessage[] = [];
        for (const sm of serverMessages) {
          if (sm.type === "relay") {
            rawMessages.push(sm.message);
          }
          const cm = relayChatMessage(agentId, sm);
          if (cm) chatMessages.push(cm);
        }

        // Skip messages already processed locally (dedup)
        const alreadyProcessed = processedCountRef.current.get(agentId) ?? 0;
        const newMessages = chatMessages.slice(alreadyProcessed);

        if (newMessages.length > 0) {
          setAgents((prev) => {
            const existing = prev.get(agentId);
            if (!existing) {
              // Agent not yet in local state — create it
              const next = new Map(prev);
              next.set(agentId, {
                status: "idle",
                messages: chatMessages, // use full history for new agent
                rawMessages,
                label: "",
                tmuxSession: null,
                createdAt: 0,
              });
              return next;
            }
            // Replace messages with full server history (source of truth)
            const next = new Map(prev);
            next.set(agentId, { ...existing, messages: chatMessages, rawMessages });
            return next;
          });
        }

        processedCountRef.current.set(agentId, chatMessages.length);
        return;
      }

      // ── history_cleared: wipe local messages for this agent ──
      if (data.type === "history_cleared") {
        updateAgent(data.agentId, (prev) => ({
          ...prev,
          messages: [],
          rawMessages: [],
        }));
        processedCountRef.current.set(data.agentId, 0);
        return;
      }

      // ── cli_disconnected: show system message ──
      if (data.type === "cli_disconnected") {
        updateAgent(data.agentId, (prev) => ({
          ...prev,
          messages: [
            ...prev.messages,
            {
              id: nextId(),
              role: "system",
              content: "CLI session ended",
              timestamp: Date.now(),
            },
          ],
        }));
        return;
      }

      // ── cli_connected: show system message ──
      if (data.type === "cli_connected") {
        updateAgent(data.agentId, (prev) => ({
          ...prev,
          messages: [
            ...prev.messages,
            {
              id: nextId(),
              role: "system",
              content: "CLI reconnected",
              timestamp: Date.now(),
            },
          ],
        }));
        return;
      }

      // ── agent_list: reconcile sidebar state from server ──
      if (data.type === "agent_list") {
        const serverAgents = data.agents as AgentInfo[];
        setAgents((prev) => {
          const next = new Map(prev);
          const serverIds = new Set(serverAgents.map((a) => a.agentId));

          // Update or add agents from server
          for (const info of serverAgents) {
            const existing = next.get(info.agentId);
            if (existing) {
              next.set(info.agentId, {
                ...existing,
                status: info.status,
                tmuxSession: info.tmuxSession,
                label: info.label,
              });
            } else {
              next.set(info.agentId, {
                status: info.status,
                messages: [],
                rawMessages: [],
                label: info.label,
                tmuxSession: info.tmuxSession,
                createdAt: info.createdAt,
              });
            }
          }

          // Remove agents no longer on the server
          for (const id of next.keys()) {
            if (!serverIds.has(id)) {
              next.delete(id);
            }
          }

          return next;
        });
        setAgentOrder(serverAgents.map((a) => a.agentId));
        return;
      }

      // ── spawned: auto-select the newly created agent ──
      if (data.type === "spawned") {
        setActiveAgentId(data.agentId);
        return;
      }

      // ── status: update a specific agent's status ──
      if (data.type === "status") {
        updateAgent(data.agentId, (prev) => ({ ...prev, status: data.status }));
        return;
      }

      // ── error: append to agent's message list ──
      if (data.type === "error") {
        updateAgent(data.agentId, (prev) => ({
          ...prev,
          messages: [
            ...prev.messages,
            {
              id: nextId(),
              role: "system",
              content: `Error: ${data.error}`,
              timestamp: Date.now(),
            },
          ],
        }));
        // Track processed count for dedup
        processedCountRef.current.set(
          data.agentId,
          (processedCountRef.current.get(data.agentId) ?? 0) + 1
        );
        return;
      }

      // ── relay: append claude message to agent's history ──
      if (data.type === "relay") {
        const agentId = data.agentId;
        const rawMsg = data.message;
        const chatMsg = relayChatMessage(agentId, data);

        updateAgent(agentId, (prev) => ({
          ...prev,
          rawMessages: [...prev.rawMessages, rawMsg],
          messages: chatMsg ? [...prev.messages, chatMsg] : prev.messages,
        }));
        if (chatMsg) {
          // Track processed count for dedup
          processedCountRef.current.set(
            agentId,
            (processedCountRef.current.get(agentId) ?? 0) + 1
          );
        }
        return;
      }
    };
  }, [updateAgent]);

  useEffect(() => {
    connect();
    return () => {
      if (reconnectTimer.current) clearTimeout(reconnectTimer.current);
      wsRef.current?.close();
    };
  }, [connect]);

  const send = useCallback((data: object) => {
    if (wsRef.current?.readyState === WebSocket.OPEN) {
      wsRef.current.send(JSON.stringify(data));
    }
  }, []);

  const spawnAgent = useCallback(
    (prompt: string) => {
      send({ type: "spawn", prompt });
    },
    [send]
  );

  const sendMessage = useCallback(
    (content: string) => {
      if (!activeAgentId) return;
      // Optimistically add user message to local state
      updateAgent(activeAgentId, (prev) => ({
        ...prev,
        messages: [
          ...prev.messages,
          {
            id: nextId(),
            role: "user",
            content,
            timestamp: Date.now(),
          },
        ],
      }));
      send({ type: "send_message", agentId: activeAgentId, content });
    },
    [send, activeAgentId, updateAgent]
  );

  const respondToControl = useCallback(
    (requestId: string, allow: boolean) => {
      if (!activeAgentId) return;
      send({ type: "control_response", agentId: activeAgentId, request_id: requestId, allow });
      updateAgent(activeAgentId, (prev) => ({
        ...prev,
        messages: prev.messages.map((m) =>
          m.controlRequest?.id === requestId
            ? { ...m, controlRequest: { ...m.controlRequest, resolved: true } }
            : m
        ),
      }));
    },
    [send, activeAgentId, updateAgent]
  );

  /** Respond to an AskUserQuestion control request with the user's selections. */
  const respondToUserQuestion = useCallback(
    (requestId: string, answers: Record<string, string>) => {
      if (!activeAgentId) return;
      send({
        type: "control_response",
        agentId: activeAgentId,
        request_id: requestId,
        allow: true,
        answers,
      });
      updateAgent(activeAgentId, (prev) => ({
        ...prev,
        messages: prev.messages.map((m) =>
          m.userQuestion?.requestId === requestId
            ? { ...m, userQuestion: { ...m.userQuestion, resolved: true } }
            : m
        ),
      }));
    },
    [send, activeAgentId, updateAgent]
  );

  // ── Agent management actions ──────────────────────────────────────────────

  const killAgent = useCallback(
    (agentId: string) => {
      send({ type: "kill_agent", agentId });
    },
    [send]
  );

  const deleteAgent = useCallback(
    (agentId: string) => {
      send({ type: "delete_agent", agentId });
      // Deselect if we just deleted the active agent
      setActiveAgentId((prev) => (prev === agentId ? null : prev));
    },
    [send]
  );

  const renameAgent = useCallback(
    (agentId: string, label: string) => {
      send({ type: "rename_agent", agentId, label });
    },
    [send]
  );

  const clearHistory = useCallback(
    (agentId: string) => {
      send({ type: "clear_history", agentId });
    },
    [send]
  );

  // ── Task actions ──────────────────────────────────────────────────────────

  const createTask = useCallback(
    (title: string, description: string, priority: TaskPriority) => {
      send({ type: "create_task", title, description, priority });
    },
    [send]
  );

  const updateTask = useCallback(
    (taskId: string, updates: Partial<Pick<Task, "title" | "description" | "status" | "priority">>) => {
      send({ type: "update_task", taskId, updates });
    },
    [send]
  );

  const deleteTask = useCallback(
    (taskId: string) => {
      send({ type: "delete_task", taskId });
    },
    [send]
  );

  const delegateTask = useCallback(
    (taskId: string) => {
      send({ type: "delegate_task", taskId });
    },
    [send]
  );

  // Derived values for the active agent
  const activeAgent = activeAgentId ? agents.get(activeAgentId) : undefined;
  const activeStatus = useMemo<AgentStatus>(
    () => activeAgent?.status ?? "idle",
    [activeAgent?.status]
  );
  const activeMessages = useMemo<ChatMessage[]>(
    () => activeAgent?.messages ?? [],
    [activeAgent?.messages]
  );
  const activeRawMessages = useMemo<ClaudeMessage[]>(
    () => activeAgent?.rawMessages ?? [],
    [activeAgent?.rawMessages]
  );

  return {
    connected,
    agents,
    agentOrder,
    activeAgentId,
    setActiveAgentId,
    activeStatus,
    activeMessages,
    activeRawMessages,
    spawnAgent,
    sendMessage,
    respondToControl,
    respondToUserQuestion,
    killAgent,
    deleteAgent,
    renameAgent,
    clearHistory,
  };
}

"use client";

/**
 * React hook that manages the WebSocket connection to the thos relay server.
 *
 * Supports multiple concurrent agents. Each agent has its own status,
 * message history, label, and tmux session name tracked in a Map keyed
 * by agent ID. The `activeAgentId` determines which agent's chat is shown.
 *
 * Resilience features:
 * - Handles `message_history` replay from server on connect/reconnect.
 * - Handles `cli_disconnected` / `cli_connected` events.
 * - Deduplicates messages using a per-agent Set of seen message IDs.
 * - Robust reconnection guard (clears previous timer before scheduling).
 */

import { useCallback, useEffect, useMemo, useRef, useState } from "react";
import type {
  AgentInfo,
  AgentStatus,
  ChatMessage,
  ClaudeAssistant,
  ClaudeControlRequest,
  ClaudeMessage,
  ClaudeResult,
  ClaudeSystemInit,
  ServerMessage,
  ServerMessageHistory,
  ServerTaskList,
  ServerTaskUpdated,
  ServerTaskDeleted,
  Task,
  TaskPriority,
  ToolCallInfo,
  UserQuestion,
} from "@/lib/types";

const WS_URL = "ws://localhost:9900/browser";

/** Per-agent client state. */
export interface AgentClientState {
  status: AgentStatus;
  messages: ChatMessage[];
  /** Raw Claude NDJSON messages for debug view. */
  rawMessages: ClaudeMessage[];
  label: string;
  tmuxSession: string | null;
  createdAt: number;
}

/**
 * Extract displayable text from a Claude assistant message.
 * Content blocks may be text, tool_use, or tool_result — each is
 * handled defensively since the array structure can vary.
 */
function extractText(msg: ClaudeAssistant): string {
  const blocks = msg.message?.content;
  if (!blocks || !Array.isArray(blocks)) return "";
  return blocks
    .map((b) => {
      if (b.type === "text") return b.text;
      if (b.type === "tool_use") return `[tool_use: ${b.name}]`;
      if (b.type === "tool_result") return `[tool_result: ${b.content}]`;
      return "";
    })
    .filter(Boolean)
    .join("\n");
}

/** Module-level counter for generating unique message IDs. */
let msgCounter = 0;
function nextId() {
  return `msg-${Date.now()}-${++msgCounter}`;
}

/**
 * Convert a server relay message into a ChatMessage, or null if it shouldn't be displayed.
 * Used both for live messages and for replaying message_history.
 */
function relayChatMessage(agentId: string, relayMsg: ServerMessage): ChatMessage | null {
  if (relayMsg.type === "relay") {
    const msg = relayMsg.message;

    if (msg.type === "system" && (msg as { subtype?: string }).subtype === "init") {
      const init = msg as ClaudeSystemInit;
      return {
        id: nextId(),
        role: "system",
        content: `Session started — model: ${init.model}, cwd: ${init.cwd}`,
        timestamp: Date.now(),
      };
    }

    if (msg.type === "assistant") {
      const assistant = msg as ClaudeAssistant;
      const text = extractText(assistant);
      if (!text) return null;

      const blocks = assistant.message?.content ?? [];
      const hasText = blocks.some((b) => b.type === "text" && b.text.trim());
      const toolCalls: ToolCallInfo[] = blocks
        .filter((b) => b.type === "tool_use")
        .map((b) => ({
          name: (b as { name: string }).name,
          toolUseId: (b as { id: string }).id,
        }));
      const isToolOnly = !hasText && toolCalls.length > 0;

      return {
        id: nextId(),
        role: "assistant",
        content: text,
        timestamp: Date.now(),
        toolCalls,
        isToolOnly,
      };
    }

    if (msg.type === "result") {
      const result = msg as ClaudeResult;
      const summary = result.is_error
        ? `Error: ${result.error}`
        : `Done — ${result.num_turns ?? "?"} turns, $${(result.cost_usd ?? 0).toFixed(4)}, ${((result.duration_ms ?? 0) / 1000).toFixed(1)}s`;
      return {
        id: nextId(),
        role: "system",
        content: summary,
        timestamp: Date.now(),
      };
    }

    if (msg.type === "control_request") {
      const cr = msg as ClaudeControlRequest;

      // AskUserQuestion gets its own UI instead of generic Allow/Deny
      if (cr.request.tool_name === "AskUserQuestion") {
        const input = cr.request.input as { questions?: UserQuestion[] };
        const questions = Array.isArray(input.questions) ? input.questions : [];
        return {
          id: nextId(),
          role: "system",
          content: "Question from Claude",
          timestamp: Date.now(),
          userQuestion: {
            requestId: cr.request_id,
            questions,
          },
        };
      }

      return {
        id: nextId(),
        role: "system",
        content: `Tool approval requested: ${cr.request.tool_name}`,
        timestamp: Date.now(),
        controlRequest: {
          id: cr.request_id,
          tool_name: cr.request.tool_name,
          input: cr.request.input,
        },
      };
    }
  }

  if (relayMsg.type === "error" && relayMsg.agentId === agentId) {
    return {
      id: nextId(),
      role: "system",
      content: `Error: ${relayMsg.error}`,
      timestamp: Date.now(),
    };
  }

  return null;
}

export function useWebSocket() {
  const wsRef = useRef<WebSocket | null>(null);
  const reconnectTimer = useRef<ReturnType<typeof setTimeout> | null>(null);
  const [connected, setConnected] = useState(false);

  // Multi-agent state
  const [agents, setAgents] = useState<Map<string, AgentClientState>>(new Map());
  const [agentOrder, setAgentOrder] = useState<string[]>([]);
  const [activeAgentId, setActiveAgentId] = useState<string | null>(null);

  // Task state
  const [tasks, setTasks] = useState<Task[]>([]);

  // Per-agent deduplication: track count of processed messages per agent
  // to avoid duplicating messages already in local state during history replay.
  const processedCountRef = useRef<Map<string, number>>(new Map());

  /** Immutably update a single agent's state in the Map. */
  const updateAgent = useCallback(
    (agentId: string, updater: (prev: AgentClientState) => AgentClientState) => {
      setAgents((prev) => {
        const existing = prev.get(agentId);
        if (!existing) return prev;
        const next = new Map(prev);
        next.set(agentId, updater(existing));
        return next;
      });
    },
    []
  );

  const connect = useCallback(() => {
    if (wsRef.current?.readyState === WebSocket.OPEN) return;
    if (wsRef.current) {
      wsRef.current.close();
      wsRef.current = null;
    }

    const ws = new WebSocket(WS_URL);
    wsRef.current = ws;

    ws.onopen = () => setConnected(true);

    ws.onclose = () => {
      setConnected(false);
      wsRef.current = null;
      // Reconnection guard: clear any existing timer before scheduling
      if (reconnectTimer.current) clearTimeout(reconnectTimer.current);
      reconnectTimer.current = setTimeout(() => connect(), 2000);
    };

    ws.onerror = () => {
      // onclose will fire after onerror, which triggers reconnect
    };

    ws.onmessage = (event) => {
      let data: ServerMessage;
      try {
        data = JSON.parse(event.data as string);
      } catch {
        return;
      }

      // ── task_list: full task list from server ──
      if (data.type === "task_list") {
        setTasks((data as ServerTaskList).tasks);
        return;
      }

      // ── task_updated: single task changed ──
      if (data.type === "task_updated") {
        const updated = (data as ServerTaskUpdated).task;
        setTasks((prev) => prev.map((t) => (t.id === updated.id ? updated : t)));
        return;
      }

      // ── task_deleted: remove task ──
      if (data.type === "task_deleted") {
        const deletedId = (data as ServerTaskDeleted).taskId;
        setTasks((prev) => prev.filter((t) => t.id !== deletedId));
        return;
      }

      // ── message_history: replay full history from server ──
      if (data.type === "message_history") {
        const historyMsg = data as ServerMessageHistory;
        const agentId = historyMsg.agentId;
        const serverMessages = historyMsg.messages;

        // Convert all server messages to ChatMessages + extract raw Claude messages
        const chatMessages: ChatMessage[] = [];
        const rawMessages: ClaudeMessage[] = [];
        for (const sm of serverMessages) {
          if (sm.type === "relay") {
            rawMessages.push(sm.message);
          }
          const cm = relayChatMessage(agentId, sm);
          if (cm) chatMessages.push(cm);
        }

        // Skip messages already processed locally (dedup)
        const alreadyProcessed = processedCountRef.current.get(agentId) ?? 0;
        const newMessages = chatMessages.slice(alreadyProcessed);

        if (newMessages.length > 0) {
          setAgents((prev) => {
            const existing = prev.get(agentId);
            if (!existing) {
              // Agent not yet in local state — create it
              const next = new Map(prev);
              next.set(agentId, {
                status: "idle",
                messages: chatMessages, // use full history for new agent
                rawMessages,
                label: "",
                tmuxSession: null,
                createdAt: 0,
              });
              return next;
            }
            // Replace messages with full server history (source of truth)
            const next = new Map(prev);
            next.set(agentId, { ...existing, messages: chatMessages, rawMessages });
            return next;
          });
        }

        processedCountRef.current.set(agentId, chatMessages.length);
        return;
      }

      // ── history_cleared: wipe local messages for this agent ──
      if (data.type === "history_cleared") {
        updateAgent(data.agentId, (prev) => ({
          ...prev,
          messages: [],
          rawMessages: [],
        }));
        processedCountRef.current.set(data.agentId, 0);
        return;
      }

      // ── cli_disconnected: show system message ──
      if (data.type === "cli_disconnected") {
        updateAgent(data.agentId, (prev) => ({
          ...prev,
          messages: [
            ...prev.messages,
            {
              id: nextId(),
              role: "system",
              content: "CLI session ended",
              timestamp: Date.now(),
            },
          ],
        }));
        return;
      }

      // ── cli_connected: show system message ──
      if (data.type === "cli_connected") {
        updateAgent(data.agentId, (prev) => ({
          ...prev,
          messages: [
            ...prev.messages,
            {
              id: nextId(),
              role: "system",
              content: "CLI reconnected",
              timestamp: Date.now(),
            },
          ],
        }));
        return;
      }

      // ── agent_list: reconcile sidebar state from server ──
      if (data.type === "agent_list") {
        const serverAgents = data.agents as AgentInfo[];
        setAgents((prev) => {
          const next = new Map(prev);
          const serverIds = new Set(serverAgents.map((a) => a.agentId));

          // Update or add agents from server
          for (const info of serverAgents) {
            const existing = next.get(info.agentId);
            if (existing) {
              next.set(info.agentId, {
                ...existing,
                status: info.status,
                tmuxSession: info.tmuxSession,
                label: info.label,
              });
            } else {
              next.set(info.agentId, {
                status: info.status,
                messages: [],
                rawMessages: [],
                label: info.label,
                tmuxSession: info.tmuxSession,
                createdAt: info.createdAt,
              });
            }
          }

          // Remove agents no longer on the server
          for (const id of next.keys()) {
            if (!serverIds.has(id)) {
              next.delete(id);
            }
          }

          return next;
        });
        setAgentOrder(serverAgents.map((a) => a.agentId));
        return;
      }

      // ── spawned: auto-select the newly created agent ──
      if (data.type === "spawned") {
        setActiveAgentId(data.agentId);
        return;
      }

      // ── status: update a specific agent's status ──
      if (data.type === "status") {
        updateAgent(data.agentId, (prev) => ({ ...prev, status: data.status }));
        return;
      }

      // ── error: append to agent's message list ──
      if (data.type === "error") {
        updateAgent(data.agentId, (prev) => ({
          ...prev,
          messages: [
            ...prev.messages,
            {
              id: nextId(),
              role: "system",
              content: `Error: ${data.error}`,
              timestamp: Date.now(),
            },
          ],
        }));
        // Track processed count for dedup
        processedCountRef.current.set(
          data.agentId,
          (processedCountRef.current.get(data.agentId) ?? 0) + 1
        );
        return;
      }

      // ── relay: append claude message to agent's history ──
      if (data.type === "relay") {
        const agentId = data.agentId;
        const rawMsg = data.message;
        const chatMsg = relayChatMessage(agentId, data);

        updateAgent(agentId, (prev) => ({
          ...prev,
          rawMessages: [...prev.rawMessages, rawMsg],
          messages: chatMsg ? [...prev.messages, chatMsg] : prev.messages,
        }));
        if (chatMsg) {
          // Track processed count for dedup
          processedCountRef.current.set(
            agentId,
            (processedCountRef.current.get(agentId) ?? 0) + 1
          );
        }
        return;
      }
    };
  }, [updateAgent]);

  useEffect(() => {
    connect();
    return () => {
      if (reconnectTimer.current) clearTimeout(reconnectTimer.current);
      wsRef.current?.close();
    };
  }, [connect]);

  const send = useCallback((data: object) => {
    if (wsRef.current?.readyState === WebSocket.OPEN) {
      wsRef.current.send(JSON.stringify(data));
    }
  }, []);

  const spawnAgent = useCallback(
    (prompt: string) => {
      send({ type: "spawn", prompt });
    },
    [send]
  );

  const sendMessage = useCallback(
    (content: string) => {
      if (!activeAgentId) return;
      // Optimistically add user message to local state
      updateAgent(activeAgentId, (prev) => ({
        ...prev,
        messages: [
          ...prev.messages,
          {
            id: nextId(),
            role: "user",
            content,
            timestamp: Date.now(),
          },
        ],
      }));
      send({ type: "send_message", agentId: activeAgentId, content });
    },
    [send, activeAgentId, updateAgent]
  );

  const respondToControl = useCallback(
    (requestId: string, allow: boolean) => {
      if (!activeAgentId) return;
      send({ type: "control_response", agentId: activeAgentId, request_id: requestId, allow });
      updateAgent(activeAgentId, (prev) => ({
        ...prev,
        messages: prev.messages.map((m) =>
          m.controlRequest?.id === requestId
            ? { ...m, controlRequest: { ...m.controlRequest, resolved: true } }
            : m
        ),
      }));
    },
    [send, activeAgentId, updateAgent]
  );

  /** Respond to an AskUserQuestion control request with the user's selections. */
  const respondToUserQuestion = useCallback(
    (requestId: string, answers: Record<string, string>) => {
      if (!activeAgentId) return;
      send({
        type: "control_response",
        agentId: activeAgentId,
        request_id: requestId,
        allow: true,
        answers,
      });
      updateAgent(activeAgentId, (prev) => ({
        ...prev,
        messages: prev.messages.map((m) =>
          m.userQuestion?.requestId === requestId
            ? { ...m, userQuestion: { ...m.userQuestion, resolved: true } }
            : m
        ),
      }));
    },
    [send, activeAgentId, updateAgent]
  );

  // ── Agent management actions ──────────────────────────────────────────────

  const killAgent = useCallback(
    (agentId: string) => {
      send({ type: "kill_agent", agentId });
    },
    [send]
  );

  const deleteAgent = useCallback(
    (agentId: string) => {
      send({ type: "delete_agent", agentId });
      // Deselect if we just deleted the active agent
      setActiveAgentId((prev) => (prev === agentId ? null : prev));
    },
    [send]
  );

  const renameAgent = useCallback(
    (agentId: string, label: string) => {
      send({ type: "rename_agent", agentId, label });
    },
    [send]
  );

  const clearHistory = useCallback(
    (agentId: string) => {
      send({ type: "clear_history", agentId });
    },
    [send]
  );

  // ── Task actions ──────────────────────────────────────────────────────────

  const createTask = useCallback(
    (title: string, description: string, priority: TaskPriority) => {
      send({ type: "create_task", title, description, priority });
    },
    [send]
  );

  const updateTask = useCallback(
    (taskId: string, updates: Partial<Pick<Task, "title" | "description" | "status" | "priority">>) => {
      send({ type: "update_task", taskId, updates });
    },
    [send]
  );

  const deleteTask = useCallback(
    (taskId: string) => {
      send({ type: "delete_task", taskId });
    },
    [send]
  );

  const delegateTask = useCallback(
    (taskId: string) => {
      send({ type: "delegate_task", taskId });
    },
    [send]
  );

  // Derived values for the active agent
  const activeAgent = activeAgentId ? agents.get(activeAgentId) : undefined;
  const activeStatus = useMemo<AgentStatus>(
    () => activeAgent?.status ?? "idle",
    [activeAgent?.status]
  );
  const activeMessages = useMemo<ChatMessage[]>(
    () => activeAgent?.messages ?? [],
    [activeAgent?.messages]
  );
  const activeRawMessages = useMemo<ClaudeMessage[]>(
    () => activeAgent?.rawMessages ?? [],
    [activeAgent?.rawMessages]
  );

  return {
    connected,
    agents,
    agentOrder,
    activeAgentId,
    setActiveAgentId,
    activeStatus,
    activeMessages,
    activeRawMessages,
    spawnAgent,
    sendMessage,
    respondToControl,
    respondToUserQuestion,
    killAgent,
    deleteAgent,
    renameAgent,
    clearHistory,
    tasks,
    createTask,
    updateTask,
    deleteTask: deleteTask,
    delegateTask,
  };
}

tool_use_result.content:
"use client";

import { useState } from "react";
import { Play, Trash2, ExternalLink, Check } from "lucide-react";
import { Button } from "@/components/ui/button";
import { cn } from "@/lib/utils";
import type { Task, TaskStatus, TaskPriority } from "@/lib/types";

const PRIORITY_COLORS: Record<TaskPriority, string> = {
  urgent: "bg-red-500/20 text-red-400 border-red-500/30",
  high: "bg-orange-500/20 text-orange-400 border-orange-500/30",
  medium: "bg-yellow-500/20 text-yellow-400 border-yellow-500/30",
  low: "bg-muted text-muted-foreground border-border",
};

const STATUS_COLORS: Record<TaskStatus, string> = {
  todo: "border-border text-muted-foreground",
  "in-progress": "bg-blue-500/20 text-blue-400 border-blue-500/30",
  done: "bg-green-500/20 text-green-400 border-green-500/30",
};

const STATUS_LABELS: Record<TaskStatus, string> = {
  todo: "todo",
  "in-progress": "in progress",
  done: "done",
};

const NEXT_STATUS: Record<TaskStatus, TaskStatus> = {
  todo: "in-progress",
  "in-progress": "done",
  done: "todo",
};

interface TaskCardProps {
  task: Task;
  onUpdate: (taskId: string, updates: Partial<Pick<Task, "title" | "description" | "status" | "priority">>) => void;
  onDelete: (taskId: string) => void;
  onDelegate: (taskId: string) => void;
  onSelectAgent: (agentId: string) => void;
}

export function TaskCard({ task, onUpdate, onDelete, onDelegate, onSelectAgent }: TaskCardProps) {
  const [editing, setEditing] = useState(false);
  const [editTitle, setEditTitle] = useState(task.title);
  const [editDesc, setEditDesc] = useState(task.description);

  const handleSaveEdit = () => {
    if (!editTitle.trim()) return;
    onUpdate(task.id, { title: editTitle.trim(), description: editDesc.trim() });
    setEditing(false);
  };

  const handleCancelEdit = () => {
    setEditTitle(task.title);
    setEditDesc(task.description);
    setEditing(false);
  };

  return (
    <div className="group rounded-md border bg-card p-3 text-xs">
      <div className="flex items-start justify-between gap-2">
        <div className="flex items-center gap-1.5 min-w-0">
          <span
            className={cn("shrink-0 rounded px-1.5 py-0.5 text-[10px] font-medium border", PRIORITY_COLORS[task.priority])}
          >
            {task.priority}
          </span>
          {editing ? (
            <input
              className="min-w-0 flex-1 bg-transparent font-medium outline-none border-b border-primary"
              value={editTitle}
              onChange={(e) => setEditTitle(e.target.value)}
              onKeyDown={(e) => {
                if (e.key === "Enter") handleSaveEdit();
                if (e.key === "Escape") handleCancelEdit();
              }}
              autoFocus
            />
          ) : (
            <span
              className={cn(
                "truncate font-medium cursor-pointer",
                task.status === "done" && "line-through text-muted-foreground"
              )}
              onDoubleClick={() => setEditing(true)}
            >
              {task.title}
            </span>
          )}
        </div>
        <div className="flex shrink-0 items-center gap-0.5 opacity-0 group-hover:opacity-100 transition-opacity">
          {!task.agentId && task.status !== "done" && (
            <Button
              variant="ghost"
              size="icon-xs"
              onClick={() => onDelegate(task.id)}
              title="Delegate to agent"
            >
              <Play className="size-3" />
            </Button>
          )}
          <Button
            variant="ghost"
            size="icon-xs"
            onClick={() => onDelete(task.id)}
            title="Delete task"
          >
            <Trash2 className="size-3" />
          </Button>
        </div>
      </div>

      {editing ? (
        <div className="mt-2 space-y-2">
          <textarea
            className="w-full rounded border bg-transparent p-1.5 text-xs outline-none resize-none"
            value={editDesc}
            onChange={(e) => setEditDesc(e.target.value)}
            rows={2}
            placeholder="Description..."
          />
          <div className="flex gap-1">
            <Button size="xs" onClick={handleSaveEdit}>
              <Check className="size-3 mr-1" />
              Save
            </Button>
            <Button size="xs" variant="ghost" onClick={handleCancelEdit}>
              Cancel
            </Button>
          </div>
        </div>
      ) : (
        task.description && (
          <p className="mt-1 text-muted-foreground line-clamp-2">{task.description}</p>
        )
      )}

      <div className="mt-2 flex items-center justify-between">
        <button
          className={cn(
            "rounded-full border px-2 py-0.5 text-[10px] font-medium transition-colors hover:brightness-125",
            STATUS_COLORS[task.status]
          )}
          onClick={() => onUpdate(task.id, { status: NEXT_STATUS[task.status] })}
          title={`Click to change to "${STATUS_LABELS[NEXT_STATUS[task.status]]}"`}
        >
          {STATUS_LABELS[task.status]}
        </button>

        {task.agentId && (
          <button
            className="flex items-center gap-1 text-[10px] text-primary hover:underline"
            onClick={() => onSelectAgent(task.agentId!)}
          >
            <ExternalLink className="size-2.5" />
            view agent
          </button>
        )}
      </div>
    </div>
  );
}

"use client";

import { useState } from "react";
import { Plus } from "lucide-react";
import { Button } from "@/components/ui/button";
import type { TaskPriority } from "@/lib/types";

interface TaskCreateFormProps {
  onCreate: (title: string, description: string, priority: TaskPriority) => void;
}

const PRIORITIES: TaskPriority[] = ["low", "medium", "high", "urgent"];

export function TaskCreateForm({ onCreate }: TaskCreateFormProps) {
  const [title, setTitle] = useState("");
  const [description, setDescription] = useState("");
  const [priority, setPriority] = useState<TaskPriority>("medium");

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    if (!title.trim()) return;
    onCreate(title.trim(), description.trim(), priority);
    setTitle("");
    setDescription("");
    setPriority("medium");
  };

  return (
    <form onSubmit={handleSubmit} className="space-y-2 border-b p-3">
      <input
        className="w-full rounded border bg-transparent px-2 py-1.5 text-xs outline-none focus:border-primary"
        placeholder="Task title..."
        value={title}
        onChange={(e) => setTitle(e.target.value)}
      />
      <textarea
        className="w-full rounded border bg-transparent px-2 py-1.5 text-xs outline-none resize-none focus:border-primary"
        placeholder="Description (optional)..."
        value={description}
        onChange={(e) => setDescription(e.target.value)}
        rows={2}
      />
      <div className="flex items-center justify-between">
        <select
          className="rounded border bg-transparent px-2 py-1 text-xs outline-none"
          value={priority}
          onChange={(e) => setPriority(e.target.value as TaskPriority)}
        >
          {PRIORITIES.map((p) => (
            <option key={p} value={p}>
              {p}
            </option>
          ))}
        </select>
        <Button type="submit" size="xs" disabled={!title.trim()}>
          <Plus className="size-3 mr-1" />
          Create
