 6→  variable: "--font-jetbrains-mono",
 7→  subsets: ["latin"],
 8→});
 9→
10→export const metadata: Metadata = {
11→  title: "thos",
12→  description: "the orchestrator you never knew you needed",
13→};
14→
15→export default function RootLayout({
16→  children,
17→}: Readonly<{
18→  children: React.ReactNode;
19→}>) {
20→  return (
21→    <html lang="en" className="dark" suppressHydrationWarning>
22→      <body className={`${jetbrainsMono.variable} font-mono antialiased`}>
23→        {children}
24→      </body>
25→    </html>
26→  );
