281→/** Inline input for renaming an agent. */
282→function RenameInput({
283→  initialValue,
284→  onConfirm,
285→  onCancel,
286→}: {
287→  initialValue: string;
288→  onConfirm: (value: string) => void;
289→  onCancel: () => void;
290→}) {
291→  const [value, setValue] = useState(initialValue);
292→  const inputRef = useRef<HTMLInputElement>(null);
293→
294→  useEffect(() => {
295→    inputRef.current?.focus();
296→    inputRef.current?.select();
297→  }, []);
298→
299→  function handleKeyDown(e: React.KeyboardEvent) {
300→    e.stopPropagation();
301→    if (e.key === "Enter") {
302→      const trimmed = value.trim();
303→      if (trimmed) onConfirm(trimmed);
304→      else onCancel();
305→    } else if (e.key === "Escape") {
306→      onCancel();
307→    }
308→  }
309→
310→  return (
311→    <input
312→      ref={inputRef}
313→      type="text"
314→      value={value}
315→      onChange={(e) => setValue(e.target.value)}
316→      onKeyDown={handleKeyDown}
317→      onBlur={() => {
318→        const trimmed = value.trim();
319→        if (trimmed && trimmed !== initialValue) onConfirm(trimmed);
320→        else onCancel();
321→      }}
322→      onClick={(e) => e.stopPropagation()}
323→      className="flex-1 rounded border bg-background px-1 py-0 text-xs outline-none focus:ring-1 focus:ring-ring"
324→    />
325→  );
326→}
